from collections import deque
def queue_enqueue_dequeue():
    q = deque()
    ops = []
    cmds = [['enq', 1], ['enq', 2], ['enq', 3], 'deq', 'deq', 'deq']
    for cmd in cmds:
        if cmd == 'enq':
            q.append(1)
            ops.append(('enq', 1))
        else:
            v = q.popleft() if q else None
            ops.append(('deq', v))
    return ops

